/* ================= BIG IDEAS ================= */
function dotsRow(n,cls){const r=el('div','srow');const a=[];for(let i=0;i<n;i++){const d=el('div','it2'+(cls?' '+cls:''));d.innerHTML='<svg viewBox="0 0 40 40"><circle cx="20" cy="20" r="15" fill="var(--dot)"/></svg>';a.push(d);r.appendChild(d)}r.items=a;return r}
function pairUp(n){const g=el('div','pairs');for(let i=0;i<n;i++){const d=el('div','it2'+(i===n-1&&n%2?' alone':''));d.innerHTML='<svg viewBox="0 0 40 40"><circle cx="20" cy="20" r="15" fill="var(--dot)"/></svg>';g.appendChild(d)}return g}
/* ================= WAYS OF THINKING: bar models, working backwards, tricks with names ================= */
/* a bar model: parts drawn to scale inside one bar, the whole as a bracket above; or two bars lined up with the gap bracketed below. '?' marks the unknown */
function barSvg(o){const W=480,pad=12,H=o.compare?150:104;let h=`<svg viewBox="0 0 ${W+2*pad} ${H}" class="barm">`;
  const seg=(x,y,w,t,col,q,hl)=>`<rect x="${x}" y="${y}" width="${w}" height="44" rx="8" fill="${q?'var(--card)':hl?'var(--sun)':col}" stroke="${q?'var(--accent)':'var(--fg)'}" stroke-width="2.5"${q?' stroke-dasharray="7 5"':''}/><text x="${x+w/2}" y="${y+30}" text-anchor="middle" font-family="var(--display)" font-size="21" font-weight="700" fill="${q?'var(--accent)':'#1a1a1a'}">${t}</text>`;
  const brace=(x1,x2,y,t,below,hl)=>`<path d="M${x1} ${y} v${below?8:-8} H${x2} v${below?-8:8}" fill="none" stroke="var(--accent)" stroke-width="2.5"/>${hl?`<rect x="${(x1+x2)/2-22}" y="${(below?y+32:y-14)-19}" width="44" height="26" rx="13" fill="var(--sun)"/>`:''}<text x="${(x1+x2)/2}" y="${below?y+32:y-14}" text-anchor="middle" font-family="var(--display)" font-size="21" font-weight="700" fill="var(--accent)">${t}</text>`;
  if(o.parts){const tot=o.parts.reduce((s,p)=>s+p.n,0),u=W/tot;let x=pad;if(o.whole!=null&&o.whole!=='')h+=brace(pad,pad+W,34,o.whole,false,o.wholeH);for(const p of o.parts){h+=seg(x,44,p.n*u,p.t,p.col||'var(--sky)',p.q,p.h);x+=p.n*u}}
  else{const [a,b]=o.compare,u=W/Math.max(a.n,b.n);h+=seg(pad,8,a.n*u,a.t,a.col||'var(--sky)',a.q);h+=seg(pad,64,b.n*u,b.t,b.col||'var(--sun)',b.q);const x1=pad+Math.min(a.n,b.n)*u,x2=pad+Math.max(a.n,b.n)*u;if(o.gap!=null)h+=brace(x1,x2,116,o.gap,true)}
  return h+'</svg>'}
/* rows of dots for the trick pictures: hl highlights the last few of a row, gone fades the last few */
function dotRows(rows){const r=26,g=8,w=Math.max(...rows.map(x=>x.n))*(r+g)+g;let h=`<svg viewBox="0 0 ${w} ${rows.length*(r+g)+g}" style="width:${Math.min(w,460)}px;max-width:100%">`;
  rows.forEach((row,ri)=>{for(let i=0;i<row.n;i++){const gone=row.gone&&i>=row.n-row.gone,hl=row.hl&&i>=row.n-row.hl;h+=`<circle cx="${g+i*(r+g)+r/2}" cy="${g+ri*(r+g)+r/2}" r="${r/2}" fill="${hl?'var(--sun)':row.col||'var(--dot)'}" opacity="${gone?.2:1}" stroke="var(--fg)" stroke-width="1.2"/>`}});return h+'</svg>'}

skill({id:'bar',room:'story',title:'Draw the bar',idea:'bars',levels:4,grow:lv=>['','Now a part is hidden, not the whole.','Now two bars, lined up: how many more?','Now you pick the bar that fits the story.'][lv-1],
  async teach(lv,L){currentThing='marbles';const box=el('div','nline');const big=el('div','bigword','');
    if(lv===1){L.say('A <em>bar</em> is a picture of a story. 4 red marbles and 3 blue marbles. Watch them squeeze into one bar.');const r=row('');r.classList.add('wide');L.scene.append(r,box,big);const A=[];for(let i=0;i<7;i++){const d=dot('');A.push(d);r.appendChild(d)}await appear(A,'',110);await L.wait(700);r.remove();box.innerHTML=barSvg({parts:[{n:4,t:4,col:'var(--accent)'},{n:3,t:3}],whole:'?'});await L.wait(1200);
      L.say('The red part and the blue part sit side by side. The <em>whole bar</em> is all of them together. 4 and 3: the whole is <em>7</em>.');box.innerHTML=barSvg({parts:[{n:4,t:4,col:'var(--accent)'},{n:3,t:3}],whole:7});big.innerHTML='4 + 3 = <em>7</em>';await L.wait(1600);L.say('The parts are what we know. The whole bar is the question. Now you try.')}
    else if(lv===2){L.scene.append(box,big);L.say('This time we know the <em>whole</em>: 9 marbles. 5 are red. The blue part is hidden.');box.innerHTML=barSvg({parts:[{n:5,t:5,col:'var(--accent)'},{n:4,t:'?',q:1}],whole:9});await L.wait(1800);L.say('The whole bar is 9. The red part fills 5 of it. What is left is the blue part: count up from 5 to 9. <em>4</em>.');box.innerHTML=barSvg({parts:[{n:5,t:5,col:'var(--accent)'},{n:4,t:4}],whole:9});big.innerHTML='9 − 5 = <em>4</em>';await L.wait(1600);L.say('A hidden part is the whole take away the other part. Now you try.')}
    else if(lv===3){L.scene.append(box,big);L.say('Two people, two bars, lined up at the left. 8 for me, 5 for Max.');box.innerHTML=barSvg({compare:[{n:8,t:'Pip 8'},{n:5,t:'Max 5'}]});await L.wait(1600);L.say('My bar <em>sticks out</em> past his. The bit that sticks out is how many more I have. Count it: 6, 7, 8. <em>3</em> more.');box.innerHTML=barSvg({compare:[{n:8,t:'Pip 8'},{n:5,t:'Max 5'}],gap:3});big.innerHTML='8 − 5 = <em>3</em>';await L.wait(1600);L.say('"How many more" is the part that sticks out. Now you try.')}
    else{L.scene.append(box,big);L.say('Stories come in three shapes. <em>Both parts, whole hidden:</em> "4 red and 3 blue, how many in all?"');box.innerHTML=barSvg({parts:[{n:4,t:4,col:'var(--accent)'},{n:3,t:3}],whole:'?'});await L.wait(1700);L.say('<em>Whole known, a part hidden:</em> "7 marbles, 4 are red, how many blue?"');box.innerHTML=barSvg({parts:[{n:4,t:4,col:'var(--accent)'},{n:3,t:'?',q:1}],whole:7});await L.wait(1700);L.say('<em>Two bars:</em> "I have 7, Max has 4, how many more?" Read the story, then pick the bar with that shape. Now you try.');box.innerHTML=barSvg({compare:[{n:7,t:'Pip 7'},{n:4,t:'Max 4'}],gap:'?'})}},
  mount(lv){const k=KID(),thing=pick(THINGS),who=pick(['Max','Lila','Sam','Nia']);currentThing=thing;
    const box=el('div','nline');const story=el('div','story');
    if(lv<4){let text,ans,spec,clue1,clue2,why,book,sense,guess,reasons,ways;
      if(lv===1){const a=rnd(2,6),b=rnd(2,6);ans=a+b;text=`${k} has ${a} red ${thing} and ${b} blue ${thing}. How many ${thing} in all?`;spec=d=>({parts:[{n:a,t:a,col:'var(--accent)'},{n:b,t:b}],whole:d?ans:'?'});clue1='The two parts sit side by side. The whole bar is both of them together.';clue2=`Count on from ${a}: ${b} more.`;why=`${a} and ${b} together fill the whole bar: ${ans}.`;book=`drew a bar for ${a} and ${b} and found the whole, ${ans}`;sense=v=>v<=Math.max(a,b)?{q:`You said ${v}. The parts are ${a} and ${b}. Can the whole bar be ${v}, no longer than one of its parts?`,opts:['yes','no'],ans:'no',why:`The whole bar is longer than either part, so the answer is more than ${Math.max(a,b)}.`}:null;guess={q:`Before the number: is the whole bar more or fewer than ${Math.max(a,b)}?`,opts:[{t:'more',ok:1,why:'Yes: both parts together is more than either part. Now the number.'},{t:'fewer',why:`The whole holds both parts, so it is more than ${Math.max(a,b)}. Now the number.`}]};reasons={q:`Why is it ${ans}?`,opts:[{t:`Because ${a} red and ${b} blue is ${ans} all together`,ok:1},{t:`Because blue is more than red`,no:'Which colour has more does not tell us how many in all. Put them together.'},{t:`Because the whole bar is always 10`,no:`The whole bar is whatever the two parts make: ${a} and ${b}.`}],why:`${a} and ${b} fill the whole bar: ${ans}.`};ways={q:'Show me another way to find the whole.',opts:[{t:`Start at ${a} and count ${b} more`,ok:1},{t:'Draw them all and count them',ok:1},{t:`Take ${a} away from ${b}`,no:'Taking away makes less. The story puts them together.'}],why:'Counting on and counting them all give the same answer.'}}
      else if(lv===2){const w=rnd(6,12),a=rnd(2,w-2);ans=w-a;text=`${k} has ${w} ${thing}. ${a} are red and the rest are blue. How many are blue?`;spec=d=>({parts:[{n:a,t:a,col:'var(--accent)'},{n:ans,t:d?ans:'?',q:!d}],whole:w});clue1=`The whole bar is ${w}. The red part is ${a}. The blue part is what is left.`;clue2=`Count up from ${a} to ${w}.`;why=`${w} take away the ${a} red leaves ${ans} blue.`;book=`found the hidden part of a bar: ${w} is ${a} and ${ans}`;sense=v=>v>=w?{q:`You said ${v}. The whole bar is ${w}. Can a part be ${v}, as long as the whole bar or longer?`,opts:['yes','no'],ans:'no',why:`A part is shorter than the whole, so the answer is less than ${w}.`}:null;guess={q:`Before the number: is the blue part more or fewer than ${w}?`,opts:[{t:'fewer',ok:1,why:'Yes: a part is always smaller than the whole. Now the number.'},{t:'more',why:`A part sits inside the whole, so it is fewer than ${w}. Now the number.`}]};reasons={q:`Why is it ${ans}?`,opts:[{t:`Because ${a} red and ${ans} blue make ${w}`,ok:1},{t:`Because ${w} + ${a} = ${w+a}`,no:'That adds the whole and the red part. The blue part is what is left over.'},{t:`Because blue is my favourite colour`,no:'A favourite is not a reason! Check: do the parts make the whole?'}],why:`${a} + ${ans} = ${w}. The blue part is ${ans}.`};ways={q:'Show me another way to find the blue part.',opts:[{t:`Count up from ${a} to ${w}`,ok:1},{t:`Take ${a} away from ${w}`,ok:1},{t:`Add ${a} and ${w}`,no:'That makes more than the whole. We want the bit that is missing.'}],why:'Counting up and taking away both find the missing bit.'}}
      else{const a=rnd(5,12),b=rnd(2,a-1);ans=a-b;text=`${k} has ${a} ${thing}. ${who} has ${b}. How many more does ${k} have?`;spec=d=>({compare:[{n:a,t:`${k} ${a}`},{n:b,t:`${who} ${b}`}],gap:d?ans:'?'});clue1='Line the two bars up. The bit that sticks out is the answer.';clue2=`Count up from ${b} to ${a}.`;why=`${k}'s bar sticks out ${ans} past ${who}'s.`;book=`compared two bars and found the difference, ${ans}`;sense=v=>v>=a?{q:`You said ${v} more. ${k}'s whole bar is ${a}. Can the bit that sticks out be ${v}?`,opts:['yes','no'],ans:'no',why:`The bit that sticks out is shorter than ${k}'s whole bar, so the answer is less than ${a}.`}:v===a+b?{q:`You said ${v}. Did you put the two bars together?`,opts:['yes','no'],ans:'yes',why:`"How many more" is the gap between the bars, not both bars together.`}:null;guess={q:`Before the number: is "how many more" bigger or smaller than ${a}?`,opts:[{t:'smaller',ok:1,why:`Yes: the bit that sticks out is only part of ${k}'s bar. Now the number.`},{t:'bigger',why:`The gap is part of ${k}'s ${a}, so it is smaller. Now the number.`}]};reasons={q:`Why is it ${ans}?`,opts:[{t:`Because from ${b} you need ${ans} more to get to ${a}`,ok:1},{t:`Because ${a} + ${b} = ${a+b}`,no:'That is both of them together. "How many more" is the gap between them.'},{t:`Because ${k} has more`,no:`That says who has more, not how many more. Count the gap.`}],why:`From ${b} up to ${a} is ${ans}: the bit that sticks out.`};ways={q:'Show me another way to find how many more.',opts:[{t:`Count up from ${b} to ${a}`,ok:1},{t:`Take ${b} away from ${a}`,ok:1},{t:`Add ${a} and ${b}`,no:'Together is not the question. The question is the gap.'}],why:'Counting up and taking away both find the gap.'}}
      prompt.textContent='Read the story. The bar shows it. What is the ?';story.textContent=text;box.innerHTML=barSvg(spec(false));stage.append(story,readBtn(()=>text),box);
      help({book,clues:[clue1,clue2],answer:ans,why,sense,guess,reasons,ways,show:()=>{box.innerHTML=barSvg(spec(true))}});
      controls.appendChild(numpad((v,nm)=>{if(v===ans){lock(nm);box.innerHTML=barSvg(spec(true));const sc=stage.querySelector('.sense');if(sc)sc.remove();win(`${cheer()} ${why}`)}else{miss(ctx.hints===0?clue1:clue2);senseCard(v)}}))}
    else{const a=rnd(2,5),b=rnd(a+2,a+6);const kind=pick(['whole','part','more']);
      const text=kind==='whole'?`${k} has ${a} red ${thing} and ${b} blue ${thing}. How many ${thing} in all?`:kind==='part'?`${k} has ${b} ${thing}. ${a} are red. How many are blue?`:`${k} has ${b} ${thing}. ${who} has ${a}. How many more does ${k} have?`;
      const bars={whole:barSvg({parts:[{n:a,t:a,col:'var(--accent)'},{n:b,t:b}],whole:'?'}),part:barSvg({parts:[{n:a,t:a,col:'var(--accent)'},{n:b-a,t:'?',q:1}],whole:b}),more:barSvg({compare:[{n:b,t:`${k} ${b}`},{n:a,t:`${who} ${a}`}],gap:'?'})};
      const why={whole:`Both parts are known, ${a} and ${b}, and the whole bar is the question.`,part:`The whole bar is ${b}, one part is ${a}, and the other part is hidden.`,more:`Two people, two bars lined up: the question is the bit that sticks out.`}[kind];
      prompt.textContent='Read the story. Which bar shows it?';story.textContent=text;stage.append(story,readBtn(()=>text));
      help({book:`picked the right bar for a story about ${thing}`,clues:['Is the question "how many in all", "how many are left", or "how many more"?',kind==='more'?'Two people means two bars.':kind==='whole'?'When we know both parts, the ? goes over the whole bar.':'When we know the whole, the ? is a part inside the bar.'],answer:null,why,show:()=>{controls.querySelectorAll('.choice').forEach(c=>{if(c.dataset.kind===kind)c.classList.add('hit')})}});
      const opts=shuffle(['whole','part','more']).map(kd=>{const d=el('div','barpick');d.innerHTML=bars[kd];return{node:d,kd}});
      const ch=choices(opts,(o,b)=>{if(o.kd===kind){b.classList.add('hit');lock(ch);win(`${cheer()} ${why}`)}else{b.classList.add('miss');b.disabled=true;miss(ctx.hints===0?ctx.help.clues[0]:ctx.help.clues[1])}});ch.querySelectorAll('.choice').forEach((c,i)=>c.dataset.kind=opts[i].kd);ch.classList.add('barpicks');controls.appendChild(ch)}}});

/* working backwards: the end is known, the start is the question; undo each step from the last one back */
const UNDO={'+':(n)=>`take ${n} away`,'-':(n)=>`put ${n} back`,x2:()=>'halve it','/2':()=>'double it'};
const APPLY={'+':(v,n)=>v+n,'-':(v,n)=>v-n,x2:v=>v*2,'/2':v=>v/2};
const INV={'+':(v,n)=>v-n,'-':(v,n)=>v+n,x2:v=>v/2,'/2':v=>v*2};
function rewindStory(lv,k,who,thing){for(let t=0;t<40;t++){let start,steps;
    if(lv===1){start=rnd(2,9);const op=pick(['+','-']);steps=[{op,n:rnd(1,5)}]}
    else if(lv===2){start=rnd(2,12);steps=[{op:pick(['+','-']),n:rnd(1,6)},{op:pick(['+','-']),n:rnd(1,6)}]}
    else{start=rnd(2,8);const d=pick(['x2','/2']);steps=shuffle([{op:d,n:0},{op:pick(['+','-']),n:rnd(1,5)}])}
    let v=start,ok=true;const vals=[start];for(const s of steps){if(s.op==='/2'&&v%2)ok=false;v=APPLY[s.op](v,s.n);if(v<1||v>20||v!==Math.floor(v))ok=false;vals.push(v)}
    if(!ok||v===start)continue;
    const said=steps.map(s=>s.op==='+'?`${k} got ${s.n} more`:s.op==='-'?`${k} gave ${s.n} away`:s.op==='x2'?`${who} gave ${k} the same again, so they doubled`:`${k} gave half of them away`);
    const labs=steps.map(s=>s.op==='+'?`got ${s.n} more`:s.op==='-'?`gave ${s.n} away`:s.op==='x2'?'doubled':'gave half away');
    return{start,steps,vals,end:v,said,labs,text:`${k} had some ${thing}. ${said.map(s=>s[0].toUpperCase()+s.slice(1)).join('. Then ')}. Now ${k} has ${v}. How many did ${k} start with?`}}return null}
skill({id:'rewind',room:'puz',title:'Rewind it',idea:'backwards',levels:3,grow:lv=>['','Now two things happen before the end.','Now doubling and halving join in.'][lv-1],
  async teach(lv,L){const w=el('div','walk');const big=el('div','bigword','');L.scene.append(w,big);
    if(lv===1){L.say('I walked <em>forward</em> 3 steps and landed on 8. Where did I start? Nobody saw. So I walk <em>backwards</em> 3 steps.');let pos=8;walkTo(w,pos);big.textContent='8';await L.wait(1500);for(let i=0;i<3;i++){pos--;walkTo(w,pos);big.textContent=String(pos);playNote(pos);await L.wait(650)}big.innerHTML='8 − 3 = <em>5</em>: I started on 5';await L.wait(900);L.say('Forward 3 is undone by back 3. To find the start, go to the end and <em>undo</em> what happened. Now you try.')}
    else if(lv===2){L.say('Two things happened: I got 4 more, then I gave 2 away, and now I have 9. To rewind, undo the <em>last</em> thing first, like taking off shoes before socks.');w.remove();const ch=el('div','chain');L.scene.insertBefore(ch,big);ch.innerHTML=`<span class="node q">?</span><span class="arrow">got 4 more</span><span class="node q">?</span><span class="arrow">gave 2 away</span><span class="node">9</span>`;await L.wait(1800);const ns=ch.querySelectorAll('.node');ns[1].textContent='11';ns[1].classList.remove('q');ns[1].classList.add('glow');big.innerHTML='undo "gave 2 away": put 2 back. 9 + 2 = <em>11</em>';await L.wait(1700);ns[0].textContent='7';ns[0].classList.remove('q');ns[0].classList.add('glow');big.innerHTML='undo "got 4 more": take 4 away. 11 − 4 = <em>7</em>';await L.wait(1500);L.say('Last thing first, then the one before. I started with <em>7</em>. Now you try.')}
    else{L.say('A new kind of step: <em>doubling</em>. I had some, Max gave me the same again, and now I have 10. What undoes doubling? <em>Halving</em>.');w.remove();const r=row('');r.classList.add('wide');L.scene.insertBefore(r,big);currentThing='marbles';for(let i=0;i<10;i++)r.appendChild(dot(''));await L.wait(1500);[...r.children].slice(5).forEach(d=>d.classList.add('gone'));big.innerHTML='half of 10 is <em>5</em>';await L.wait(1400);L.say('And if I gave <em>half</em> away, I undo that by doubling what is left. Now you try.')}},
  mount(lv){const k=KID(),thing=pick(THINGS),who=pick(['Max','Lila','Sam','Nia']);currentThing=thing;const st=rewindStory(lv,k,who,thing);
    prompt.textContent='Read the story. Then rewind it.';const box=el('div','story',st.text);stage.append(box,readBtn(()=>st.text));
    const ch=el('div','chain');st.steps.forEach((s,i)=>{ch.appendChild(el('span','node q','?'));ch.appendChild(el('span','arrow',st.labs[i]))});ch.appendChild(el('span','node',st.end));stage.appendChild(ch);
    const nodes=ch.querySelectorAll('.node'),arrows=ch.querySelectorAll('.arrow');
    const rewind=async()=>{for(let i=st.steps.length-1;i>=0;i--){arrows[i].classList.add('undo');arrows[i].textContent=UNDO[st.steps[i].op](st.steps[i].n);await wait(500);nodes[i].textContent=st.vals[i];nodes[i].classList.remove('q');nodes[i].classList.add('glow');playNote(st.vals[i]);await wait(700)}};
    const last=st.steps[st.steps.length-1];const beforeLast=st.vals[st.vals.length-2];
    const steps=st.steps.map((s,i)=>`undo "${st.labs[i]}": ${UNDO[s.op](s.n)}, ${st.vals[i]}`).reverse();
    const up=st.steps.every(x=>x.op==='+'||x.op==='x2'),down=st.steps.every(x=>x.op==='-'||x.op==='/2');const sense=v=>up&&v>=st.end?{q:`You said ${v}. ${k} only got more and ended with ${st.end}. Can the start be ${v}, as many as the end or more?`,opts:['yes','no'],ans:'no',why:`Getting more makes the end bigger than the start. The start is less than ${st.end}.`}:down&&v<=st.end?{q:`You said ${v}. ${k} only gave some away and ended with ${st.end}. Can the start be ${v}, no more than the end?`,opts:['yes','no'],ans:'no',why:`Giving away makes the end smaller than the start. The start is more than ${st.end}.`}:null;
    const guess=up||down?{q:`Before the number: did ${k} start with more or fewer than ${st.end}?`,opts:[{t:'fewer',ok:up,why:up?`Yes: ${k} only got more, so the start was smaller. Now the number.`:`${k} only gave away, so the start was bigger than ${st.end}. Now the number.`},{t:'more',ok:down,why:down?`Yes: ${k} only gave away, so the start was bigger. Now the number.`:`${k} only got more, so the start was smaller than ${st.end}. Now the number.`}]}:null;const fwd=`start at ${st.start}, ${st.labs.join(', then ')}, and you get ${st.end}`;const reasons={q:`Why is the start ${st.start}?`,opts:[{t:`Because if you ${fwd}`,ok:1},{t:`Because ${st.end} is the biggest number`,no:'Biggest is not a reason. Check it: does the story work from there?'},{t:st.steps.length===1?`Because ${st.end} ${st.steps[0].op==='+'?'+':'−'} ${st.steps[0].n} = ${st.steps[0].op==='+'?st.end+st.steps[0].n:st.end-st.steps[0].n}`:'Because you add all the numbers up',no:'That goes forwards from the end. To find the start you go backwards and undo.'}],why:`Check it forwards: ${fwd}. It works.`};
    help({sense,guess,reasons,book:`rewound a story and found that ${k} started with ${st.start}`,clues:['Start at the end and walk backwards. Undo the last thing first.',`${k} ended with ${st.end}. To undo "${st.labs[st.steps.length-1]}", ${UNDO[last.op](last.n)}: that gives ${beforeLast}.`],answer:st.start,why:`Start at ${st.end}. ${steps.join('. ')}. So ${k} started with ${st.start}.`,show:rewind});
    controls.appendChild(numpad((v,nm)=>{if(v===st.start){lock(nm);const sc=stage.querySelector('.sense');if(sc)sc.remove();win(`${cheer()} ${ctx.help.why}`);rewind()}else{miss(ctx.hints===0?`You went forwards. Start at ${st.end} and undo the last thing.`:ctx.help.clues[1]);senseCard(v)}}))}});

/* tricks with names: knowing the name tells you what to do */
const TRICKS={
  dbl:{name:'Doubles',fits:(a,b,sub)=>sub?a===2*b:a===b,no:'Doubles need the same number twice.',why:(a,b,sub)=>sub?`${b} + ${b} = ${a}, so ${a} − ${b} = ${b}. A double, backwards.`:`${a} + ${a} is a double. Doubles are fast: ${a+a}.`,pic:(a,b,sub)=>dotRows(sub?[{n:b},{n:b,gone:b}]:[{n:a},{n:a}])},
  near:{name:'Near doubles',fits:(a,b,sub)=>!sub&&Math.abs(a-b)===1,no:'Near doubles are one apart, like 6 and 7.',why:(a,b)=>{const s=Math.min(a,b);return `${a} + ${b} is almost a double: ${s} + ${s} = ${2*s}, and 1 more is ${2*s+1}.`},pic:(a,b)=>{const s=Math.min(a,b);return dotRows([{n:s},{n:s+1,hl:1}])}},
  tenmore:{name:'Ten and more',fits:(a,b,sub)=>!sub&&(a===10||b===10),no:'Ten and more needs a 10 in it.',why:(a,b)=>{const o=a===10?b:a;return `10 and ${o} more is just ${10+o}: a ten and some ones.`},pic:(a,b)=>dotRows([{n:10,col:'var(--sky)'},{n:a===10?b:a}])},
  on:{name:'Count on',fits:(a,b,sub)=>!sub&&Math.min(a,b)<=2&&Math.max(a,b)>=4,no:'Count on is for adding a tiny number, 1 or 2.',why:(a,b)=>{const big=Math.max(a,b),s=Math.min(a,b);return `Start at the big number, ${big}, and count on ${s}: ${Array.from({length:s},(_,i)=>big+i+1).join(', ')}.`},pic:(a,b)=>{const d=el('div','nline');d.innerHTML=numberLine(20,Math.max(a,b),a+b,Math.min(a,b));return d.outerHTML}},
  ten:{name:'Make ten',fits:(a,b,sub)=>!sub&&Math.max(a,b)>=7&&Math.min(a,b)>=3&&a+b>10&&Math.abs(a-b)>1,no:'Make ten is for a big number like 8 or 9 plus a few more.',why:(a,b)=>{const big=Math.max(a,b),s=Math.min(a,b),m=10-big;return `Take ${m} from ${s} to fill the ten. 10 and ${s-m} more is ${a+b}.`},pic:(a,b)=>{const big=Math.max(a,b),s=Math.min(a,b),m=10-big;return dotRows([{n:10,hl:m},{n:s-m}])}},
  back:{name:'Count back',fits:(a,b,sub)=>sub&&b<=3,no:'Count back is for taking away a tiny number.',why:(a,b)=>`Start at ${a} and count back ${b}: ${Array.from({length:b},(_,i)=>a-i-1).join(', ')}.`,pic:(a,b)=>{const d=el('div','nline');d.innerHTML=numberLine(20,a,a-b,-b);return d.outerHTML}},
  fromten:{name:'Take from ten',fits:(a,b,sub)=>sub&&a>10&&a<20&&b>a-10&&b>=4,no:'Take from ten needs a number past 10 and a big take-away.',why:(a,b)=>{const c=a-10;return `${a} is 10 and ${c}. Take ${b} from the 10: ${10-b}. Then ${10-b} and ${c} is ${a-b}.`},pic:(a,b)=>dotRows([{n:10,gone:b,col:'var(--sky)'},{n:a-10}])}};
function trickProblem(lv){const sub=lv===3;for(let t=0;t<60;t++){let id,a,b;
    if(!sub){id=pick(lv===1?['dbl','near','on','tenmore']:['dbl','near','on','tenmore','ten','ten']);
      if(id==='dbl'){a=b=rnd(2,lv===1?5:9)}else if(id==='near'){a=rnd(2,lv===1?4:8);b=a+1;if(Math.random()<.5)[a,b]=[b,a]}else if(id==='on'){a=rnd(4,lv===1?8:17);b=rnd(1,2);if(Math.random()<.5)[a,b]=[b,a]}else if(id==='tenmore'){a=10;b=rnd(1,9);if(Math.random()<.5)[a,b]=[b,a]}else{a=rnd(7,9);b=rnd(3,Math.min(6,a-2));if(Math.random()<.5)[a,b]=[b,a]}}
    else{id=pick(['back','fromten','dbl']);if(id==='back'){a=rnd(5,20);b=rnd(1,3)}else if(id==='fromten'){a=rnd(11,18);b=rnd(Math.max(4,a-9),9)}else{b=rnd(3,9);a=2*b}}
    if(!TRICKS[id].fits(a,b,sub))continue;const others=Object.keys(TRICKS).filter(x=>x!==id&&!TRICKS[x].fits(a,b,sub)&&(sub?['back','fromten','dbl'].includes(x):x!=='back'&&x!=='fromten'));if(others.length<2)continue;
    return{id,a,b,sub,ans:sub?a-b:a+b,opts:shuffle([id].concat(shuffle(others).slice(0,2)))}}return null}
skill({id:'trick',room:'add',title:'Name the trick',idea:'tricks',levels:3,grow:lv=>['','Now Make ten joins in, and you use the trick to find the answer.','Now the tricks are for taking away.'][lv-1],
  async teach(lv,L){const pic=el('div','ta');const big=el('div','bigword','');L.scene.append(pic,big);
    if(lv===1){L.say('Tricks have <em>names</em>. When you know the name, you know what to do. <em>Doubles</em>: 4 + 4. Two rows the same. 8.');pic.innerHTML=TRICKS.dbl.pic(4,4);big.innerHTML='4 + 4 = <em>8</em>';await L.wait(2000);L.say('<em>Near doubles</em>: 4 + 5. A double, and one more. 8 and 1 is 9.');pic.innerHTML=TRICKS.near.pic(4,5);big.innerHTML='4 + 5 = 8 + 1 = <em>9</em>';await L.wait(2000);L.say('<em>Count on</em>: 7 + 2. Start at the big one and hop twice: 8, 9.');pic.innerHTML=TRICKS.on.pic(7,2);big.innerHTML='7 + 2: 8, <em>9</em>';await L.wait(2000);L.say('<em>Ten and more</em>: 10 + 3. A ten and some ones: 13. Now look at a sum and say which trick fits.')}
    else if(lv===2){L.say('A new trick: <em>Make ten</em>. 8 + 5. Eight is nearly ten. Borrow 2 from the 5 to fill the ten.');pic.innerHTML=dotRows([{n:8},{n:5}]);await L.wait(1800);pic.innerHTML=TRICKS.ten.pic(8,5);big.innerHTML='10 + 3 = <em>13</em>';await L.wait(1600);L.say('Ten and 3 more: 13. Make ten works whenever one number is 7, 8 or 9. Now you name the trick, then use it.')}
    else{L.say('Taking away has tricks too. <em>Take from ten</em>: 13 − 5. Thirteen is a ten and 3. Take the 5 from the ten.');pic.innerHTML=dotRows([{n:10,col:'var(--sky)'},{n:3}]);await L.wait(1700);pic.innerHTML=TRICKS.fromten.pic(13,5);big.innerHTML='10 − 5 = 5, and 3 more: <em>8</em>';await L.wait(1800);L.say('<em>Count back</em> is for taking a tiny number: 9 − 2 is 8, 7. And a <em>double</em> backwards: 14 − 7 = 7, because 7 + 7 = 14. Now you try.')}},
  mount(lv){const p=trickProblem(lv);const T=TRICKS[p.id];const sign=p.sub?'−':'+';const eqText=`${p.a} ${sign} ${p.b}`;
    prompt.textContent=`Which trick helps with ${eqText.replace(/ /g,'\u00a0')}?`;const eq=el('div','eq',eqText);const pic=el('div','ta');stage.append(eq,pic);
    const useIt=lv>1;const why=T.why(p.a,p.b,p.sub);
    help({book:useIt?`used the ${T.name} trick to find ${eqText} = ${p.ans}`:`named the ${T.name} trick for ${eqText}`,clues:[p.sub?'Is the take-away tiny? Is the big number past 10? Is it a double backwards?':'Are the two numbers the same? One apart? Is one of them 10? Is one tiny?',`${T.name}. ${why}`],answer:useIt?p.ans:T.name,why,show:()=>{pic.innerHTML=T.pic(p.a,p.b,p.sub);controls.querySelectorAll('.choice').forEach(c=>{if(c.textContent===T.name)c.classList.add('hit')})}});
    const ch=choices(p.opts.map(id=>TRICKS[id].name),(o,b)=>{if(o===T.name){b.classList.add('hit');lock(ch);pic.innerHTML=T.pic(p.a,p.b,p.sub);
        if(!useIt)win(`${cheer()} ${why}`);else{say(`Yes, ${T.name}. ${why.split('. ')[0]}. So ${eqText} = ?`);controls.appendChild(numpad((v,nm)=>{if(v===p.ans){lock(nm);win(`${cheer()} ${why}`)}
          else if((p.id==='on'&&v===p.ans-1)||(p.id==='back'&&v===p.ans+1)){const st=p.id==='on'?Math.max(p.a,p.b):p.a,n=p.id==='on'?Math.min(p.a,p.b):p.b;miss(`${st} is where we start, not a hop. Finger on ${st}, then hop ${n} time${n===1?'':'s'}: ${why.split(': ')[1]}`)}
          else miss(ctx.hints===0?why.split('. ')[0]+'.':why)}))}}
      else{b.classList.add('miss');b.disabled=true;miss(ctx.hints===0?TRICKS[p.opts.find(id=>TRICKS[id].name===o)].no:`Look again: ${why.split('. ')[0]}.`)}});controls.appendChild(ch)}});

/* "Does that make sense?": after a wrong number, a card asks one question about the story's shape so the child checks the answer against the story, not the sum.
   A game sets help({sense:v=>({q,opts,ans,why,no})|null}); the card does not count as a hint */
function senseCard(v){const h=ctx.help;if(!h||!h.sense||ctx.done)return;let s=null;try{s=h.sense(v)}catch(e){}if(!s)return;const old=stage.querySelector('.sense');if(old)old.remove();
  const card=el('div','note sense',`<small>Does that make sense?</small>${s.q}`);const r=el('div','row');s.opts.forEach(o=>{const b=el('button','choice',o);b.onclick=()=>{if(o===s.ans){b.classList.add('hit');r.querySelectorAll('button').forEach(x=>x.disabled=true);say(`${s.why} Try again.`,false);bugs('think')}else{b.classList.add('miss');b.disabled=true;say(s.no||'Look at the story again.',false)}};r.appendChild(b)});card.appendChild(r);stage.appendChild(card);card.scrollIntoView({block:'nearest',behavior:'smooth'})}

/* story detective: read a story the way a detective reads a room. Level 1 has no numbers at all; level 2 is the ritual, know / want / picture / solve; level 3 moves the unknown */
const DET_NAMES=['Max','Lila','Sam','Nia'];
function detectiveStory(lv,k,thing){const who=pick(DET_NAMES);
  if(lv===1){const t=pick(['got','gave','same','compare','compare2','ate']);
    if(t==='got')return{text:`${who} had some ${thing}. Then ${who} got some more. Does ${who} have more or fewer ${thing} now?`,q:'more or fewer?',opts:['more','fewer','the same'],ans:'more',why:`Getting more always makes more, even with no numbers.`};
    if(t==='gave')return{text:`${who} had some ${thing}. Then ${who} gave some to ${k}. Does ${who} have more or fewer ${thing} now?`,q:'more or fewer?',opts:['more','fewer','the same'],ans:'fewer',why:`Giving some away always leaves fewer.`};
    if(t==='ate')return{text:`${k} had some ${thing} and ${who} had some too. ${who} lost a few. Who has fewer now than before?`,q:'who?',opts:[who,k,'both'],ans:who,why:`Only ${who} lost some. ${k}'s pile did not change.`};
    if(t==='same')return{text:`${who} had some ${thing}. ${who} counted them, then put them back in the box. Does ${who} have more or fewer ${thing} now?`,q:'more or fewer?',opts:['more','fewer','the same'],ans:'the same',why:`Counting and moving them changes nothing. Same pile, same number.`};
    if(t==='compare')return{text:`${who} has more ${thing} than ${k}. Who has fewer?`,q:'who?',opts:[k,who,'nobody'],ans:k,why:`If ${who} has more, then ${k} has fewer. Same fact, other side.`};
    return{text:`${k} and ${who} have the same number of ${thing}. Then ${k} gets one more. Who has more now?`,q:'who?',opts:[k,who,'nobody'],ans:k,why:`They were equal, and only ${k} got more.`}}
  if(lv===2){const kind=pick(['whole','part','more']);const a=rnd(2,6),b=rnd(a+1,a+6);let text,facts,wrongFacts,qs,ans,pic,sense,why;
    if(kind==='whole'){text=`${k} has ${a} red ${thing} and ${b} blue ${thing}. How many ${thing} does ${k} have in all?`;facts=[`${a} are red`,`${b} are blue`];wrongFacts=[`${a+2} are red`,`${who} has some too`];qs={right:'How many in all?',wrong:['How many are red?','How many more are blue?']};ans=a+b;why=`${a} and ${b} together make ${ans}.`;
      sense=v=>v<=b?{q:`You said ${v}. ${k} has ${a} red and ${b} blue. Can all of them together be ${v}, no more than the blue ones alone?`,opts:['yes','no'],ans:'no',why:`Together is always more than one part. The answer is bigger than ${b}.`}:null}
    else if(kind==='part'){text=`${k} has ${b} ${thing}. ${a} of them are red and the rest are blue. How many are blue?`;facts=[`${b} in all`,`${a} are red`];wrongFacts=[`${b} are blue`,`${who} has ${a}`];qs={right:'How many are blue?',wrong:['How many in all?','How many are red?']};ans=b-a;why=`${b} in all, take away the ${a} red: ${ans} blue.`;
      sense=v=>v>=b?{q:`You said ${v}. There are ${b} in all. Can the blue part be ${v}, as big as everything or bigger?`,opts:['yes','no'],ans:'no',why:`A part is always smaller than the whole. The answer is less than ${b}.`}:null}
    else{text=`${k} has ${b} ${thing}. ${who} has ${a}. How many more does ${k} have than ${who}?`;facts=[`${k} has ${b}`,`${who} has ${a}`];wrongFacts=[`${who} has ${b}`,`${k} has ${a+b}`];qs={right:`How many more does ${k} have?`,wrong:['How many in all?',`How many does ${who} have?`]};ans=b-a;why=`Count up from ${a} to ${b}: ${ans} more.`;
      sense=v=>v>=b?{q:`You said ${v} more. ${k} only has ${b}. Can ${k} have ${v} more than ${who}?`,opts:['yes','no'],ans:'no',why:`"More" is the gap between them, smaller than what ${k} has.`}:v===a+b?{q:`You said ${v}. Did you add ${k}'s and ${who}'s together?`,opts:['yes','no'],ans:'yes',why:`"How many more" is not "how many together". It is the gap.`}:null}
    pic={whole:barSvg({parts:[{n:a,t:a,col:'var(--accent)'},{n:b,t:b}],whole:'?'}),part:barSvg({parts:[{n:a,t:a,col:'var(--accent)'},{n:b-a,t:'?',q:1}],whole:b}),more:barSvg({compare:[{n:b,t:`${k} ${b}`},{n:a,t:`${who} ${a}`}],gap:'?'})};
    return{text,facts,wrongFacts,qs,ans,kind,pic,sense,why,picWhy:{whole:'Both parts are known, so the ? sits over the whole bar.',part:'The whole is known, so the ? is a part inside the bar.',more:'Two people, two bars, and the ? is the bit that sticks out.'}[kind]}}
  const s=rnd(2,9),n=rnd(1,6),e=s+n;const kind=pick(['start','change','end']);const chain=(x,y,z)=>`<div class="chain h"><span class="node${x==='?'?' q':''}">${x}</span><span class="arrow">got ${y} more</span><span class="node${z==='?'?' q':''}">${z}</span></div>`;
  const text=kind==='start'?`${k} had some ${thing}. ${k} got ${n} more. Now ${k} has ${e}. How many did ${k} have at the start?`:kind==='change'?`${k} had ${s} ${thing}. ${k} got some more. Now ${k} has ${e}. How many did ${k} get?`:`${k} had ${s} ${thing}. ${k} got ${n} more. How many does ${k} have now?`;
  const facts={start:[`got ${n} more`,`has ${e} now`],change:[`had ${s}`,`has ${e} now`],end:[`had ${s}`,`got ${n} more`]}[kind];const wrongFacts={start:[`had ${e} at the start`,`gave ${n} away`],change:[`got ${n} more`,`gave some away`],end:[`has ${e} now`,`gave ${n} away`]}[kind];
  const qs={start:{right:'How many at the start?',wrong:['How many now?','How many did they get?']},change:{right:`How many did ${k} get?`,wrong:['How many now?','How many at the start?']},end:{right:'How many now?',wrong:['How many at the start?',`How many did ${k} get?`]}}[kind];
  const ans={start:s,change:n,end:e}[kind];const why={start:`Start at ${e} and undo "got ${n} more": take ${n} away. ${s}.`,change:`From ${s} up to ${e} is ${n}.`,end:`${s} and ${n} more is ${e}.`}[kind];
  const pic={start:chain('?',n,e),change:chain(s,'?',e),end:chain(s,n,'?')};const picWhy={start:'The ? is at the start, before anything happened.',change:'The ? is the change in the middle: what was added.',end:'The ? is at the end, after the change.'}[kind];
  const sense=kind==='start'?v=>v>=e?{q:`You said ${v}. ${k} got more and ended with ${e}. Can the start be ${v}, as many as the end or more?`,opts:['yes','no'],ans:'no',why:`Getting more makes the end bigger than the start. The start is less than ${e}.`}:null:kind==='change'?v=>v>=e?{q:`You said ${k} got ${v}. ${k} only has ${e} now. Can ${k} have got ${v}?`,opts:['yes','no'],ans:'no',why:`What was added is less than the total now, ${e}.`}:null:v=>v<=s?{q:`You said ${v}. ${k} had ${s} and got more. Can ${k} have ${v} now, no more than before?`,opts:['yes','no'],ans:'no',why:`Getting more means the end is bigger than ${s}.`}:null;
  return{text,facts,wrongFacts,qs,ans,kind,pic,picWhy,sense,why}}
skill({id:'detective',room:'story',title:'Story detective',idea:'reading',levels:3,grow:lv=>['','Now the stories have numbers, and you find the clues before you solve.','Now the hidden number can be anywhere in the story.'][lv-1],
  async teach(lv,L){const big=el('div','bigword','');const box=el('div','story');L.scene.append(box,big);
    if(lv===1){L.say('A story has a <em>shape</em> even with no numbers in it. Listen: Max had some marbles. Then he got some more.');box.textContent='Max had some marbles. Then he got some more.';await L.wait(1800);big.innerHTML='got more → <em>more</em>';L.say('No numbers, and you still know: Max has <em>more</em> now. Getting more always makes more.');await L.wait(1700);box.textContent='Lila had some marbles. Then she gave some away.';big.innerHTML='gave away → <em>fewer</em>';L.say('Giving away always makes <em>fewer</em>. First read what <em>happened</em>. The numbers come later. Now you try.')}
    else if(lv===2){L.say('A detective does not grab the first clue. Four steps, in order: <em>know</em>, <em>want</em>, <em>picture</em>, <em>solve</em>.');box.textContent='Max has 3 red marbles and 5 blue. How many in all?';await L.wait(1600);big.innerHTML='<em>know</em>: 3 red, 5 blue';L.say('<em>Know</em>: what does the story tell us? 3 red, 5 blue.');await L.wait(1500);big.innerHTML='<em>want</em>: how many in all?';L.say('<em>Want</em>: what is it asking? How many in all.');await L.wait(1500);const b=el('div','nline');b.innerHTML=barSvg({parts:[{n:3,t:3,col:'var(--accent)'},{n:5,t:5}],whole:'?'});L.scene.insertBefore(b,big);big.innerHTML='<em>picture</em>: parts and a whole';L.say('<em>Picture</em>: both parts known, the whole is the ?. Only now, <em>solve</em>: 8. The sum is the last thing, and the easiest. Now you try.')}
    else{L.say('The ? can hide <em>anywhere</em>. Same story, three places.');box.textContent='Max had 5. He got 3 more. Now he has 8.';const c=el('div');L.scene.insertBefore(c,big);c.innerHTML='<div class="chain h"><span class="node">5</span><span class="arrow">got 3</span><span class="node q">?</span></div>';big.innerHTML='"How many now?" the ? is at the <em>end</em>';await L.wait(1800);c.innerHTML='<div class="chain h"><span class="node">5</span><span class="arrow">got ?</span><span class="node">8</span></div>';big.innerHTML='"How many did he get?" the ? is in the <em>middle</em>';await L.wait(1800);c.innerHTML='<div class="chain h"><span class="node q">?</span><span class="arrow">got 3</span><span class="node">8</span></div>';big.innerHTML='"How many at the start?" the ? is at the <em>start</em>';L.say('Find where the ? hides <em>before</em> you touch a number. Now you try.')}},
  mount(lv){const k=KID(),thing=pick(THINGS);currentThing=thing;const st=detectiveStory(lv,k,thing);
    const box=el('div','story',st.text);stage.append(box,readBtn(()=>st.text));
    if(lv===1){prompt.textContent='No numbers. Just read what happened.';
      help({book:`read a story with no numbers and knew the answer was "${st.ans}"`,clues:['What happened in the story? Did someone get more, or give some away, or did nothing change?',st.why],answer:st.ans,why:st.why,show:()=>{controls.querySelectorAll('.choice').forEach(c=>{if(c.textContent===st.ans)c.classList.add('hit')})}});
      const ch=choices(shuffle(st.opts),(o,b)=>{if(o===st.ans){b.classList.add('hit');lock(ch);win(`${cheer()} ${st.why}`)}else{b.classList.add('miss');b.disabled=true;miss(ctx.hints===0?ctx.help.clues[0]:st.why)}});controls.appendChild(ch);return}
    /* the ritual: know (tap the two facts), want (tap the question), picture (tap the shape), solve (type it) */
    const stepEl=el('div','instr','');stage.appendChild(stepEl);let step=0;const found=new Set();
    const picWhy=st.picWhy;
    const guess=st.kind==='whole'?{q:`Before the number: is "in all" more or fewer than each part?`,opts:[{t:'more',ok:1,why:'Yes: all together is more than any one part. Now the number.'},{t:'fewer',why:'Together is more than one part alone. Now the number.'}]}:st.kind==='part'||st.kind==='more'?{q:'Before the number: is the answer bigger or smaller than the whole?',opts:[{t:'smaller',ok:1,why:'Yes: a part, or a gap, is smaller than the whole. Now the number.'},{t:'bigger',why:'A part sits inside the whole, so it is smaller. Now the number.'}]}:st.kind==='start'?{q:`Before the number: did ${k} start with more or fewer than now?`,opts:[{t:'fewer',ok:1,why:`Yes: ${k} got more, so the start was smaller. Now the number.`},{t:'more',why:`${k} got more, so the start was smaller than now. Now the number.`}]}:st.kind==='change'?{q:`Before the number: is what ${k} got more or fewer than ${k} has now?`,opts:[{t:'fewer',ok:1,why:`Yes: what was added is only part of what ${k} has now. Now the number.`},{t:'more',why:`What was added is part of the total now, so it is fewer. Now the number.`}]}:st.kind==='end'?{q:`Before the number: does ${k} end with more or fewer than at the start?`,opts:[{t:'more',ok:1,why:'Yes: getting more makes more. Now the number.'},{t:'fewer',why:'Getting more makes more, not fewer. Now the number.'}]}:null;
    help({guess:null,detGuess:guess,reasons:{q:'Why did you pick that picture?',opts:[{t:{whole:'Because I knew both parts and wanted all of them together',part:'Because I knew all of them and wanted just one part',more:'Because it was two people and I wanted the gap between them',start:'Because the ? was at the start, before anything happened',change:'Because the ? was what got added in the middle',end:'Because the ? was at the end, after it happened'}[st.kind],ok:1},{t:'Because it had big numbers',no:'The numbers do not pick the picture. The question does.'},{t:'Because it was the first one',no:'First is not a reason. Which picture asks the same thing as the story?'}],why:st.picWhy},book:`read a story like a detective and solved it: ${st.ans}`,clues:['Detectives go in order: what do we know, what do we want, which picture, then solve.',{toString:()=>step===0?'Find the two things the story really says. One card has the wrong number.':step===1?'The question is the last sentence of the story. Which card says the same thing?':step===2?picWhy:st.why}],answer:st.ans,why:st.why,sense:st.sense,
      show:()=>{controls.querySelectorAll('.choice').forEach(c=>{if(c.dataset.right==='1')c.classList.add('hit')})}});
    const render=()=>{controls.innerHTML='';
      if(step===0){stepEl.innerHTML='<b>Know.</b> Tap the two things the story tells us.';const cards=shuffle(st.facts.map(f=>({t:f,ok:true})).concat(st.wrongFacts.map(f=>({t:f,ok:false}))));
        const ch=choices(cards.map(c=>c.t),(o,b)=>{const c=cards.find(x=>x.t===o);if(c.ok){b.classList.add('hit');b.disabled=true;found.add(o);if(found.size===2){say('Those are the clues.',true);setTimeout(()=>{step=1;render()},1100)}}else{b.classList.add('miss');b.disabled=true;miss(ctx.hints===0?'That is not in the story. Read it again.':`The story says: ${st.facts.join(', and ')}.`)}});ch.querySelectorAll('.choice').forEach((b,i)=>{if(cards[i].ok)b.dataset.right='1'});ch.classList.add('cards');controls.appendChild(ch)}
      else if(step===1){stepEl.innerHTML='<b>Want.</b> Tap what the story is asking.';const qs=shuffle([st.qs.right].concat(st.qs.wrong));
        const ch=choices(qs,(o,b)=>{if(o===st.qs.right){b.classList.add('hit');lock(ch);say('That is the question.',true);setTimeout(()=>{step=2;render()},1100)}else{b.classList.add('miss');b.disabled=true;miss(ctx.hints===0?'Read the last sentence of the story. That is the question.':`The story asks: ${st.qs.right}`)}});ch.querySelectorAll('.choice').forEach((b,i)=>{if(qs[i]===st.qs.right)b.dataset.right='1'});ch.classList.add('cards');controls.appendChild(ch)}
      else if(step===2){stepEl.innerHTML='<b>Picture.</b> Tap the picture that fits.';const kinds=shuffle(Object.keys(st.pic));
        const opts=kinds.map(kd=>{const d=el('div','barpick');d.innerHTML=st.pic[kd];return{node:d,kd}});const ch=choices(opts,(o,b)=>{if(o.kd===st.kind){b.classList.add('hit');lock(ch);say(picWhy,true);setTimeout(()=>{step=3;render()},900)}else{b.classList.add('miss');b.disabled=true;miss(ctx.hints===0?'Look at where the ? is. Which picture asks the same question as the story?':picWhy)}});ch.querySelectorAll('.choice').forEach((b,i)=>{if(opts[i].kd===st.kind)b.dataset.right='1'});ch.classList.add('barpicks');controls.appendChild(ch)}
      else{stepEl.innerHTML='<b>Solve.</b> Now the number.';const pic=el('div','nline');pic.innerHTML=st.pic[st.kind];stage.insertBefore(pic,stepEl);
        controls.appendChild(numpad((v,nm)=>{if(v===st.ans){lock(nm);const sc=stage.querySelector('.sense');if(sc)sc.remove();win(`${cheer()} ${st.why}`)}else{miss(ctx.hints===0?'Look at the picture. Where is the ?':st.why);senseCard(v)}}));if(ctx.help.detGuess)guessGate(ctx.help.detGuess)}
      if(step>0)controls.appendChild(helpRow())}; // the engine adds the help row after the first render
    render()}});

/* same story, three unknowns: one story told three times with the ? in a different place each time. The star is for all three; the point is that the shape stays and only the question moves */
function threeStory(lv,k,thing,who){if(lv<3){const s=rnd(2,9),n=rnd(1,6),got=lv===1||Math.random()<.5;const e=got?s+n:s-n;if(e<1)return threeStory(lv,k,thing,who);const act=got?`got ${n} more`:`gave ${n} away`;
    const chain=(x,y,z,hl)=>`<div class="chain h"><span class="node${x==='?'?' q':''}${hl===0?' glow':''}">${x}</span><span class="arrow${hl===1?' hl':''}">${got?'got':'gave'} ${y}${got?' more':' away'}</span><span class="node${z==='?'?' q':''}${hl===2?' glow':''}">${z}</span></div>`;
    const rounds=[{slot:'end',text:`${k} had ${s} ${thing}. ${k} ${act}. How many does ${k} have now?`,ans:e,pic:()=>chain(s,n,'?'),done:()=>chain(s,n,e,2),hint:`The ? is at the end. Start at ${s} and ${got?'count on':'count back'} ${n}.`,why:`${s} ${got?'+':'−'} ${n} = ${e}.`},
      {slot:'change',text:`${k} had ${s} ${thing}. ${k} ${got?'got some more':'gave some away'}. Now ${k} has ${e}. How many did ${k} ${got?'get':'give away'}?`,ans:n,pic:()=>chain(s,'?',e),done:()=>chain(s,n,e,1),hint:`The ? is in the middle: the change. How far is it from ${s} to ${e}?`,why:`From ${s} to ${e} is ${n}.`},
      {slot:'start',text:`${k} had some ${thing}. ${k} ${act}. Now ${k} has ${e}. How many did ${k} have at the start?`,ans:s,pic:()=>chain('?',n,e),done:()=>chain(s,n,e,0),hint:`The ? is at the start. Begin at ${e} and undo "${act}": ${got?`take ${n} away`:`put ${n} back`}.`,why:`${e} ${got?'−':'+'} ${n} = ${s}, the start.`}];
    return{rounds:lv===1?rounds:shuffle(rounds),line:`${s} ${got?'+':'−'} ${n} = ${e}`,summary:`Same story, three questions: now, the change, the start. One picture, ${s} ${got?'+':'−'} ${n} = ${e}, answers all three.`}}
  const a=rnd(2,6),b=rnd(2,6),w=a+b;const bar=(x,y,z,hl)=>barSvg({parts:[{n:a,t:x,col:'var(--accent)',q:x==='?',h:hl==='a'},{n:b,t:y,q:y==='?',h:hl==='b'}],whole:z,wholeH:hl==='w'});
  const rounds=[{slot:'whole',text:`${k} has ${a} red ${thing} and ${b} blue ${thing}. How many in all?`,ans:w,pic:()=>bar(a,b,'?'),done:()=>bar(a,b,w,'w'),hint:`The ? is over the whole bar. Put the parts together: ${a} and ${b}.`,why:`${a} + ${b} = ${w}.`},
    {slot:'part',text:`${k} has ${w} ${thing}. ${a} are red and the rest are blue. How many are blue?`,ans:b,pic:()=>bar(a,'?',w),done:()=>bar(a,b,w,'b'),hint:`The ? is the blue part. The whole is ${w} and the red part is ${a}.`,why:`${w} − ${a} = ${b}.`},
    {slot:'otherpart',text:`${k} has ${w} ${thing}. ${b} are blue and the rest are red. How many are red?`,ans:a,pic:()=>bar('?',b,w),done:()=>bar(a,b,w,'a'),hint:`Now the ? is the red part. The whole is ${w} and the blue part is ${b}.`,why:`${w} − ${b} = ${a}.`}];
  return{rounds:shuffle(rounds),line:`${a} + ${b} = ${w}`,summary:`Same bar, three questions: the whole, the blue part, the red part. One picture, ${a} + ${b} = ${w}, answers all three.`,isBar:true}}
skill({id:'three',room:'story',title:'Same story, three unknowns',idea:'reading',levels:3,grow:lv=>['','Now the three questions come in any order, and some stories give away.','Now the story is a bar: the whole and its two parts.'][lv-1],
  async teach(lv,L){const box=el('div','story');const pic=el('div','ta');const big=el('div','bigword','');L.scene.append(box,pic,big);
    if(lv<3){L.say('One story. Max had 5, got 3 more, now has 8. Watch the <em>?</em> move. It can hide at the <em>end</em>…');box.textContent='Max had 5. He got 3 more. How many now?';pic.innerHTML='<div class="chain h"><span class="node">5</span><span class="arrow">got 3 more</span><span class="node q">?</span></div>';big.innerHTML='? at the <em>end</em>: 8';await L.wait(2000);
      L.say('…in the <em>middle</em>…');box.textContent='Max had 5. He got some more. Now he has 8. How many did he get?';pic.innerHTML='<div class="chain h"><span class="node">5</span><span class="arrow">got ? more</span><span class="node">8</span></div>';big.innerHTML='? in the <em>middle</em>: 3';await L.wait(2000);
      L.say('…or at the <em>start</em>. Three questions, one story, one picture: 5 + 3 = 8. Find the ? first, then the number is easy. Now you try all three.');box.textContent='Max had some. He got 3 more. Now he has 8. How many at the start?';pic.innerHTML='<div class="chain h"><span class="node q">?</span><span class="arrow">got 3 more</span><span class="node">8</span></div>';big.innerHTML='? at the <em>start</em>: 5'}
    else{L.say('A bar has three places for a ? too. 4 red and 3 blue: the <em>whole</em> is hidden…');box.textContent='4 red and 3 blue. How many in all?';pic.innerHTML=barSvg({parts:[{n:4,t:4,col:'var(--accent)'},{n:3,t:3}],whole:'?'});big.innerHTML='? over the <em>whole</em>: 7';await L.wait(2000);
      L.say('…or the <em>blue part</em> is hidden…');box.textContent='7 in all. 4 are red. How many blue?';pic.innerHTML=barSvg({parts:[{n:4,t:4,col:'var(--accent)'},{n:3,t:'?',q:1}],whole:7});big.innerHTML='? on a <em>part</em>: 3';await L.wait(2000);
      L.say('…or the <em>red part</em>. One bar, 4 + 3 = 7, answers all three. Now you try.');box.textContent='7 in all. 3 are blue. How many red?';pic.innerHTML=barSvg({parts:[{n:4,t:'?',col:'var(--accent)',q:1},{n:3,t:3}],whole:7});big.innerHTML='? on the <em>other part</em>: 4'}},
  mount(lv){const k=KID(),thing=pick(THINGS),who=pick(DET_NAMES);currentThing=thing;const st=threeStory(lv,k,thing,who);let i=0;
    prompt.textContent='One story, three questions. Find where the ? hides.';const steps=el('div','row three');st.rounds.forEach((r,j)=>steps.appendChild(el('span','stone'+(j===0?' now':''),j+1)));const box=el('div','story','');const rb=readBtn(()=>box.textContent);const pic=el('div',st.isBar?'nline':'ta');stage.append(steps,box,rb,pic);
    const R=()=>st.rounds[i];const render=()=>{box.textContent=R().text;pic.innerHTML=R().pic();steps.querySelectorAll('.stone').forEach((s,j)=>{s.classList.toggle('now',j===i);s.classList.toggle('lit',j<i)});ctx.help.answer=R().ans;ctx.help.why=R().why};
    help({book:`answered the same story three ways, with the ? at a different place each time (${st.line})`,clues:['Find the ? in the picture first. Is it at the start, in the middle, or at the end?',{toString:()=>R().hint}],answer:null,why:'',sense:null,reasons:{q:'Why did one picture work for all three questions?',opts:[{t:'Because it was the same story every time, only the ? moved',ok:1},{t:'Because all three answers were the same number',no:'The answers were different numbers. The story was the same.'},{t:'Because stories are always adding',no:'Some of these took away. The picture showed you which.'}],why:`The story never changed: ${st.line}. Only the question moved.`},show:()=>{pic.innerHTML=R().done()}});
    const finish=()=>{const all=el('div','ta');all.style.gap='6px';st.rounds.forEach(r=>{const d=el('div',st.isBar?'nline':'ta');d.innerHTML=r.done();all.appendChild(d)});pic.replaceWith(all);box.textContent=st.summary;win(`${cheer()} Three questions, one story: ${st.line}.`)};
    controls.appendChild(numpad((v,nm)=>{if(v===R().ans){pic.innerHTML=R().done();playNote(i*4+4);if(i===st.rounds.length-1){lock(nm);finish()}else{say(`${R().why} Now the ? moves.`,true);i++;setTimeout(()=>{if(!ctx.done)render()},1800)}}else miss(ctx.hints===0?R().hint:R().why)}));
    render()}});

